package summarytui

import (
	"context"
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/table"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/insightsdb"
)

type rootModel struct {
	ctx        context.Context
	rows       []insightsdb.SessionRow
	table      table.Model
	width      int
	height     int
	styles     styles
	detailPage *detailModel
}

type openDetailMsg struct {
	row insightsdb.SessionRow
}

type closeDetailMsg struct{}

func Run(ctx context.Context, rows []insightsdb.SessionRow) error {
	p := tea.NewProgram(newRootModel(rows), tea.WithAltScreen())
	_, err := p.Run()
	if err != nil {
		return fmt.Errorf("run summary TUI: %w", err)
	}
	return nil
}

func newRootModel(rows []insightsdb.SessionRow) rootModel {
	columns := []table.Column{
		{Title: "TIME", Width: 16},
		{Title: "AGENT", Width: 14},
		{Title: "BRANCH", Width: 24},
		{Title: "CHECKPOINT", Width: 12},
		{Title: "SUMMARY", Width: 8},
		{Title: "FACETS", Width: 7},
		{Title: "TOKENS", Width: 8},
		{Title: "TURNS", Width: 5},
	}
	t := table.New(table.WithColumns(columns), table.WithFocused(true))
	m := rootModel{
		ctx:    context.Background(),
		rows:   append([]insightsdb.SessionRow(nil), rows...),
		table:  t,
		styles: newStyles(),
		width:  100,
		height: 30,
	}
	m.rebuildTable()
	return m
}

func (m rootModel) Init() tea.Cmd {
	return nil
}

func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		if m.detailPage != nil {
			switch msg.Type {
			case tea.KeyEsc:
				return m, func() tea.Msg { return closeDetailMsg{} }
			case tea.KeyCtrlC:
				return m, tea.Quit
			}
			return m, nil
		}

		switch msg.Type {
		case tea.KeyEnter:
			if row := m.selectedRow(); row != nil {
				selected := *row
				return m, func() tea.Msg { return openDetailMsg{row: selected} }
			}
		case tea.KeyCtrlC:
			return m, tea.Quit
		}

	case openDetailMsg:
		m.detailPage = newDetailModel(m.styles, msg.row)
		return m, nil

	case closeDetailMsg:
		m.detailPage = nil
		return m, nil
	}

	var cmd tea.Cmd
	m.table, cmd = m.table.Update(msg)
	return m, cmd
}

func (m rootModel) View() string {
	if m.detailPage != nil {
		return m.detailPage.view()
	}

	var b strings.Builder
	b.WriteString("SESSION SUMMARY BROWSER\n\n")
	b.WriteString(m.table.View())
	b.WriteString("\n\nj/k navigate  enter open detail  q quit")
	return b.String()
}

func (m *rootModel) rebuildTable() {
	rows := make([]table.Row, 0, len(m.rows))
	for _, row := range m.rows {
		checkpoint := row.CheckpointID
		if len(checkpoint) > 12 {
			checkpoint = checkpoint[:12]
		}
		rows = append(rows, table.Row{
			row.CreatedAt.Format("2006-01-02 15:04"),
			row.Agent,
			truncate(row.Branch, 24),
			checkpoint,
			statusFlag(row.HasSummary),
			statusFlag(row.HasFacets),
			strconv.Itoa(row.TotalTokens),
			strconv.Itoa(row.TurnCount),
		})
	}
	m.table.SetRows(rows)
}

func (m rootModel) selectedRow() *insightsdb.SessionRow {
	idx := m.table.Cursor()
	if idx < 0 || idx >= len(m.rows) {
		return nil
	}
	return &m.rows[idx]
}
